Tile("next-up", {
  render(el){
    const list = this.events({cals:this.s.cals, once:true}), cals = this.sources("calendars"), teams = this.sources("teams");
    const e = list[0];
    el.innerHTML = "<h3>" + this.esc(this.name) + "</h3>" + (e ? "<div class=ev>" + this.esc(e.summary) + "</div><div class=isdate>" + (e.date instanceof Date && !isNaN(e.date)) + "</div>" :
      "<div class=empty>" + (cals.length ? "Nothing coming up" : "Connect a calendar") + "</div>") + "<div class=cals>" + cals.length + "</div><div class=teams>" + teams.length + "</div>";
    if (!this._tried){ this._tried = 1; this.fetch("https://api.example.com/moon.json"); }
    const fe = this.fetchError("https://api.example.com/moon.json");
    if (fe) el.innerHTML += "<div class=neterr>" + this.esc(fe) + "</div>";
  }
});
